-- V41-C3R2H: Remaining Capability / Operational Consumer Closure.
-- Eighteen active operational controls become MIGRATION_READY typed-runtime settings.
-- Bootstrap, security, configuration-infrastructure and legacy/test controls remain outside ordinary Runtime Configuration.
-- No key advances to MIGRATED; C3R3 Single Authority cutover remains mandatory.

update runtime_config_inventory_governance set authority_class='BOOTSTRAP_INFRA',mutability='RESTART_REQUIRED',consumer_contract='STARTUP_BINDING',admin_editable=false,reason='C3R2H non-runtime executable-source classification',version=version+1,updated_at=now() where configuration_key='CORE_URL' and status not in ('MIGRATED','LEGACY_RETIRED');

update runtime_config_inventory_governance set authority_class='DOMAIN_CONFIG',mutability='RESTART_REQUIRED',consumer_contract='STARTUP_BINDING',admin_editable=false,reason='C3R2H non-runtime executable-source classification',version=version+1,updated_at=now() where configuration_key='dispatch.bridge-reconciliation-ms' and status not in ('MIGRATED','LEGACY_RETIRED');














update runtime_config_inventory_governance set authority_class='BOOTSTRAP_INFRA',mutability='RESTART_REQUIRED',consumer_contract='STARTUP_BINDING',admin_editable=false,reason='C3R2H non-runtime executable-source classification',version=version+1,updated_at=now() where configuration_key='opendispatch.a0-r2.finalization.worker-id' and status not in ('MIGRATED','LEGACY_RETIRED');

