update runtime_config_inventory_governance set authority_class='TEST_RELEASE_CONFIG',mutability='RESTART_REQUIRED',consumer_contract='STARTUP_BINDING',admin_editable=false,reason='C3R2H non-runtime executable-source classification',version=version+1,updated_at=now() where configuration_key='opendispatch.a0-r4.shadow.poll-ms' and status not in ('MIGRATED','LEGACY_RETIRED');





update runtime_config_inventory_governance set authority_class='SECURITY_INVARIANT',mutability='RESTART_REQUIRED',consumer_contract='STARTUP_BINDING',admin_editable=false,reason='C3R2H non-runtime executable-source classification',version=version+1,updated_at=now() where configuration_key='opendispatch.environment-profile-validation-enabled' and status not in ('MIGRATED','LEGACY_RETIRED');

