update runtime_config_inventory_governance set authority_class='SECURITY_INVARIANT',mutability='RESTART_REQUIRED',consumer_contract='STARTUP_BINDING',admin_editable=false,reason='C3R2H non-runtime executable-source classification',version=version+1,updated_at=now() where configuration_key='resource-access.agent-runtime-enforce' and status not in ('MIGRATED','LEGACY_RETIRED');

with advanced as ( update runtime_config_inventory_governance g set status='CLASSIFIED',domain_owner=d.domain_owner,authority_class=d.authority_class,scope=d.scope,risk=d.risk,mutability=d.target_mutability,consumer_contract=d.target_consumer_contract,admin_editable=d.admin_editable,requires_approval=d.requires_approval,classified_by='v41-c3r2h-remaining-operational-consumer-closure',classified_at=now(),reason='C3R2H active typed runtime consumer classification confirmed',version=version+1 from runtime_config_definitions d where g.configuration_key=d.definition_key and g.configuration_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and g.status='DISCOVERED' returning g.configuration_key,g.source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'CLASSIFIED','DISCOVERED','CLASSIFIED','v41-c3r2h-remaining-operational-consumer-closure','C3R2H active typed runtime consumer classification confirmed',source_observation_hash,'{"stage":"V41_C3R2H_REMAINING_CAPABILITY_OPERATIONAL_CONSUMER_CLOSURE","cutover":"NOT_FINALIZED"}'::jsonb from advanced;
with advanced as ( update runtime_config_inventory_governance set status='OWNER_REVIEWED',owner_reviewed_by='remaining-operational-domain-owner',owner_reviewed_at=now(),reason='C3R2H operational consumer and validation bounds reviewed',version=version+1 where configuration_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and status='CLASSIFIED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'OWNER_REVIEWED','CLASSIFIED','OWNER_REVIEWED','remaining-operational-domain-owner','C3R2H operational consumer and validation bounds reviewed',source_observation_hash,'{"cutover":"NOT_FINALIZED"}'::jsonb from advanced;
with advanced as ( update runtime_config_inventory_governance set status='ARCHITECTURE_APPROVED',architecture_approved_by='configuration-architecture-reviewer',architecture_approved_at=now(),reason='DB authority + Redis distribution + authenticated local snapshot architecture approved',version=version+1 where configuration_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and status='OWNER_REVIEWED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'ARCHITECTURE_APPROVED','OWNER_REVIEWED','ARCHITECTURE_APPROVED','configuration-architecture-reviewer','DB authority + Redis distribution + authenticated local snapshot architecture approved',source_observation_hash,'{"cutover":"NOT_FINALIZED"}'::jsonb from advanced;
with advanced as ( update runtime_config_inventory_governance set status='MIGRATION_READY',migration_authorized_by='v41-c3r2h-remaining-operational-consumer-closure',migration_authorized_at=now(),reason='C3R2H typed runtime consumers implemented; Single Authority cutover remains pending',version=version+1 where configuration_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and status='ARCHITECTURE_APPROVED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'MIGRATION_READY','ARCHITECTURE_APPROVED','MIGRATION_READY','v41-c3r2h-remaining-operational-consumer-closure','C3R2H typed runtime consumers implemented; Single Authority cutover remains pending',source_observation_hash,'{"cutover":"NOT_FINALIZED"}'::jsonb from advanced;
do $$ declare v_ready integer; v_governance_ready integer; begin select count(*) into v_ready from runtime_config_definitions where definition_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true; if v_ready<>18 then raise exception 'C3R2H_DOMAIN_DEFINITION_CLOSURE_INCOMPLETE expected=18 actual=%',v_ready; end if; select count(*) into v_governance_ready from runtime_config_inventory_governance where configuration_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and status='MIGRATION_READY' and classified_by='v41-c3r2h-remaining-operational-consumer-closure' and owner_reviewed_by='remaining-operational-domain-owner' and architecture_approved_by='configuration-architecture-reviewer' and migration_authorized_by='v41-c3r2h-remaining-operational-consumer-closure'; if v_governance_ready<>18 then raise exception 'C3R2H_GOVERNANCE_LIFECYCLE_INCOMPLETE expected=18 actual=%',v_governance_ready; end if; if exists(select 1 from runtime_config_definitions where definition_key in ('CORE_URL','dispatch.bridge-reconciliation-ms','opendispatch.a0-r2.finalization.worker-id','opendispatch.a0-r4.shadow.batch-size','opendispatch.a0-r4.shadow.poll-ms','opendispatch.environment-profile-validation-enabled','opendispatch.runtime-configuration.distribution.node-stale-scan-ms','opendispatch.runtime-configuration.distribution.topology-reconcile-ms','opendispatch.runtime-configuration.governance.override-reconcile-ms','resource-access.agent-runtime-enforce') and (migration_authorized=true or admin_editable=true)) then raise exception 'C3R2H_NON_RUNTIME_AUTHORITY_LEAK'; end if; if (select count(*) from runtime_config_inventory_observations where configuration_key in ('CORE_URL','dispatch.bridge-reconciliation-ms','opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.a0-r2.finalization.worker-id','opendispatch.a0-r4.shadow.batch-size','opendispatch.a0-r4.shadow.poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.environment-profile-validation-enabled','opendispatch.runtime-configuration.distribution.node-stale-scan-ms','opendispatch.runtime-configuration.distribution.topology-reconcile-ms','opendispatch.runtime-configuration.governance.override-reconcile-ms','opendispatch.stage10.semantic-triage.worker-delay-ms','resource-access.agent-runtime-enforce'))<>28 then raise exception 'C3R2H_CODE_ONLY_INVENTORY_MISSING'; end if; if exists(select 1 from runtime_config_inventory_governance where configuration_key in ('opendispatch.a0-r2.conditions.batch-size','opendispatch.a0-r2.conditions.enabled','opendispatch.a0-r2.conditions.poll-ms','opendispatch.a0-r2.finalization.batch-size','opendispatch.a0-r2.finalization.claim-seconds','opendispatch.a0-r2.finalization.enabled','opendispatch.a0-r2.finalization.max-attempts','opendispatch.a0-r2.finalization.poll-ms','opendispatch.a0-r2.finalization.projection-batch-size','opendispatch.a0-r2.finalization.projection-claim-seconds','opendispatch.a0-r2.finalization.projection-enabled','opendispatch.a0-r2.finalization.projection-max-attempts','opendispatch.a0-r2.finalization.projection-poll-ms','opendispatch.analytics.projection.batch-size','opendispatch.analytics.projection.enabled','opendispatch.analytics.projection.poll-ms','opendispatch.analytics.rollup.batch-size','opendispatch.stage10.semantic-triage.worker-delay-ms') and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2H_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if; end $$;
